import{_ as t,o,c as a,a3 as r}from"./chunks/framework.Bw5kJGsQ.js";const p=JSON.parse('{"title":"Screen sizes and HiDPI","description":"How scenes are scaled to the window and to HiDPI screens, and the project settings that control it.","frontmatter":{"id":"screen-sizes","title":"Screen sizes and HiDPI","order":3,"description":"How scenes are scaled to the window and to HiDPI screens, and the project settings that control it.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/manual/screen-sizes.md"},"headers":[],"relativePath":"manual/screen-sizes.md","filePath":"en/manual/screen-sizes.md"}'),s={name:"manual/screen-sizes.md"};function d(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="screen-sizes-and-hidpi" tabindex="-1">Screen sizes and HiDPI <a class="header-anchor" href="#screen-sizes-and-hidpi" aria-label="Permalink to &quot;Screen sizes and HiDPI&quot;">​</a></h1><p>Positions, sizes and scales in a scene are in game pixels. On a HiDPI (Retina) screen they are drawn with more screen pixels, so a scene looks the same size on a 1x and a 2x screen.</p><h2 id="stretch-mode" tabindex="-1">Stretch mode <a class="header-anchor" href="#stretch-mode" aria-label="Permalink to &quot;Stretch mode {#stretch-mode}&quot;">​</a></h2><p>How a scene reacts to the window size is set by <code>window.stretch_mode</code> in the <a href="/docs/latest/api/cpp/class/atmo-project-projectsettings" class="atmo-ref atmo-ref--symbol">project settings</a>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>&quot;disabled&quot;</code> (default)</td><td>A larger window shows more of the world.</td></tr><tr><td><code>&quot;fit&quot;</code></td><td>The game is laid out for <code>window.size</code> and scales to fill the window, keeping its aspect ratio. The rest of the window shows bars in <code>window.letterbox_color</code>.</td></tr><tr><td><code>&quot;integer&quot;</code></td><td>Like <code>fit</code>, but only scales by whole numbers of screen pixels, for crisp pixel art.</td></tr></tbody></table><h2 id="texture-filter" tabindex="-1">Texture filtering <a class="header-anchor" href="#texture-filter" aria-label="Permalink to &quot;Texture filtering {#texture-filter}&quot;">​</a></h2><p><code>rendering.texture_filter</code> sets how textures are sampled when scaled:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>&quot;linear&quot;</code> (default)</td><td>Smooth</td></tr><tr><td><code>&quot;nearest&quot;</code></td><td>Sharp pixels, for pixel art</td></tr></tbody></table><p>For pixel art, combine <code>&quot;nearest&quot;</code> with the <code>&quot;integer&quot;</code> stretch mode.</p>',9)])])}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
